public void sortColors(int[] nums) {
        int n = nums.length;
        int p0 = 0;
        int p2 = n-1;
        int cur = 0;
        while(cur <= p2){
            if(nums[cur] == 0){
                swap(nums,p0,cur);
                p0++;
                cur++;
            } else if(nums[cur] == 2){
                swap(nums,cur,p2);
                p2--;
            } else {
                cur++;
            }
        }
    }

private void swap(int[] nums, int i, int j){
       int temp = nums[i];
       nums[i] = nums[j];
       nums[j] = temp;
}
